class Solution(object):
    def findLengthOfShortestSubarray(self, arr):
        """
        :type arr: List[int]
        :rtype: int
        """
        n = len(arr)
        p2 = n - 1
        while p2 > 0 and arr[p2 - 1] <= arr[p2]:
            p2 -= 1
        if p2 == 0:
            return 0
        ans = p2
        for p1 in range(n):
            while p2 < n and arr[p2] < arr[p1]:
                p2 += 1
            ans = min(ans, p2 - p1 - 1)
            if p1 + 1 < n and arr[p1] > arr[p1 + 1]:
                break
        return ans
